CREATE TABLE IF NOT EXISTS schema_migrations(version BIGINT PRIMARY KEY,applied_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL,password_hash TEXT NOT NULL,name TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('guest','operator')),test_account BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS sessions(id_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires_at BIGINT NOT NULL,csrf_token TEXT NOT NULL,created_at BIGINT NOT NULL);
 CREATE INDEX IF NOT EXISTS sessions_user ON sessions(user_id);
 CREATE TABLE IF NOT EXISTS operator_scopes(user_id TEXT NOT NULL REFERENCES users(id),group_id TEXT NOT NULL,PRIMARY KEY(user_id,group_id));
 CREATE TABLE IF NOT EXISTS workspace_groups(id TEXT PRIMARY KEY,name TEXT NOT NULL,address TEXT NOT NULL,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,base_rate_cents BIGINT NOT NULL,timezone TEXT NOT NULL,modeled BIGINT NOT NULL DEFAULT 1,description TEXT NOT NULL,hours_json TEXT NOT NULL,photos_json TEXT NOT NULL DEFAULT '[]',attributes_json TEXT NOT NULL DEFAULT '{}',access_instructions TEXT,data TEXT NOT NULL DEFAULT '{}');
 CREATE TABLE IF NOT EXISTS offices(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES workspace_groups(id),name TEXT NOT NULL,description TEXT NOT NULL,rate_cents BIGINT,modeled BIGINT NOT NULL DEFAULT 1,photos_json TEXT NOT NULL DEFAULT '[]',attributes_json TEXT NOT NULL DEFAULT '{}',device_binding_json TEXT,data TEXT NOT NULL DEFAULT '{}');
 CREATE INDEX IF NOT EXISTS offices_group ON offices(group_id);
 CREATE TABLE IF NOT EXISTS operator_device_grants(user_id TEXT NOT NULL REFERENCES users(id),room_id TEXT NOT NULL REFERENCES offices(id),PRIMARY KEY(user_id,room_id));
 CREATE TABLE IF NOT EXISTS quotes(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),room_id TEXT NOT NULL REFERENCES offices(id),start_at BIGINT NOT NULL,end_at BIGINT NOT NULL,rate_cents BIGINT NOT NULL,subtotal_cents BIGINT NOT NULL,fee_cents BIGINT NOT NULL,total_cents BIGINT NOT NULL,currency TEXT NOT NULL,expires_at BIGINT NOT NULL,data TEXT NOT NULL DEFAULT '{}');
 CREATE TABLE IF NOT EXISTS reservations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),room_id TEXT NOT NULL REFERENCES offices(id),original_room_id TEXT NOT NULL,group_id TEXT NOT NULL,quote_id TEXT NOT NULL UNIQUE,start_at BIGINT NOT NULL,end_at BIGINT NOT NULL,subtotal_cents BIGINT NOT NULL,fee_cents BIGINT NOT NULL,total_cents BIGINT NOT NULL,currency TEXT NOT NULL,status TEXT NOT NULL,payment_status TEXT NOT NULL,refund_status TEXT NOT NULL,checkout_session_id TEXT UNIQUE,payment_intent_id TEXT UNIQUE,checkout_url TEXT,hold_expires_at BIGINT,idempotency_key TEXT,revision BIGINT NOT NULL DEFAULT 0,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,data TEXT NOT NULL DEFAULT '{}',UNIQUE(user_id,idempotency_key));
 CREATE INDEX IF NOT EXISTS reservations_user ON reservations(user_id,created_at);
 CREATE INDEX IF NOT EXISTS reservations_room ON reservations(room_id,start_at,end_at);
 CREATE TABLE IF NOT EXISTS payment_events(id TEXT PRIMARY KEY,type TEXT NOT NULL,session_id TEXT,status TEXT NOT NULL,data TEXT NOT NULL,error TEXT,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL UNIQUE,stripe_refund_id TEXT UNIQUE,status TEXT NOT NULL,reason TEXT NOT NULL,amount_cents BIGINT NOT NULL,data TEXT NOT NULL DEFAULT '{}',error TEXT,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS offers(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL,room_id TEXT NOT NULL,status TEXT NOT NULL,expires_at BIGINT NOT NULL,room_revision BIGINT NOT NULL,data TEXT NOT NULL DEFAULT '{}',created_at BIGINT NOT NULL);
 CREATE INDEX IF NOT EXISTS offers_booking ON offers(booking_id,status);
 CREATE TABLE IF NOT EXISTS swaps(id TEXT PRIMARY KEY,booking_id TEXT NOT NULL,offer_id TEXT NOT NULL UNIQUE,from_room_id TEXT NOT NULL,to_room_id TEXT NOT NULL,stage TEXT NOT NULL,revision BIGINT NOT NULL DEFAULT 0,error TEXT,data TEXT NOT NULL DEFAULT '{}',created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS workflow_leases(key TEXT PRIMARY KEY,owner TEXT NOT NULL,expires_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS auth_attempts(key TEXT PRIMARY KEY,count BIGINT NOT NULL,reset_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS attention_tasks(id TEXT PRIMARY KEY,room_id TEXT NOT NULL,reason TEXT NOT NULL,status TEXT NOT NULL,assignee TEXT,resolution_evidence TEXT,created_at BIGINT NOT NULL,resolved_at BIGINT,data TEXT NOT NULL DEFAULT '{}');
 CREATE INDEX IF NOT EXISTS attention_room ON attention_tasks(room_id,status);
 CREATE TABLE IF NOT EXISTS device_commands(id TEXT PRIMARY KEY,room_id TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,job_id TEXT,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,data TEXT NOT NULL DEFAULT '{}');
 CREATE TABLE IF NOT EXISTS device_observations(id TEXT PRIMARY KEY,room_id TEXT NOT NULL,kind TEXT NOT NULL,observed_at BIGINT NOT NULL,data TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS audit_log(id TEXT PRIMARY KEY,actor TEXT NOT NULL,action TEXT NOT NULL,entity_id TEXT NOT NULL,data TEXT NOT NULL,created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,target TEXT NOT NULL,event_json TEXT NOT NULL,status TEXT NOT NULL,attempts BIGINT NOT NULL DEFAULT 0,next_attempt_at BIGINT NOT NULL,created_at BIGINT NOT NULL,delivered_at BIGINT,result_json TEXT,error TEXT,relay_message_id TEXT,last_error TEXT,completed_at BIGINT);
 CREATE INDEX IF NOT EXISTS outbox_pending ON outbox(status,next_attempt_at);
 CREATE TABLE IF NOT EXISTS processed_messages(id TEXT PRIMARY KEY,worker TEXT NOT NULL,event_id TEXT NOT NULL,status TEXT NOT NULL,result_json TEXT,error TEXT,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,UNIQUE(worker,event_id));
 CREATE TABLE IF NOT EXISTS relay_identities(name TEXT PRIMARY KEY,agent_id TEXT,token TEXT,data TEXT NOT NULL DEFAULT '{}',created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,booking_id TEXT,title TEXT NOT NULL DEFAULT 'ODAS concierge',created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,data TEXT NOT NULL DEFAULT '{}');
 CREATE INDEX IF NOT EXISTS conversations_user ON conversations(user_id,updated_at);
 CREATE TABLE IF NOT EXISTS chat_messages(sequence BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),role TEXT NOT NULL,content TEXT NOT NULL,created_at BIGINT NOT NULL,data TEXT NOT NULL DEFAULT '{}',idempotency_key TEXT UNIQUE);
 CREATE TABLE IF NOT EXISTS notifications(sequence BIGINT GENERATED BY DEFAULT AS IDENTITY UNIQUE,id TEXT PRIMARY KEY,user_id TEXT NOT NULL,booking_id TEXT,type TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,created_at BIGINT NOT NULL,read_at BIGINT,open_concierge BIGINT NOT NULL DEFAULT 0,idempotency_key TEXT UNIQUE,data TEXT NOT NULL DEFAULT '{}');
 CREATE INDEX IF NOT EXISTS notifications_user ON notifications(user_id,created_at);
 CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS room_conversation(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,room_id TEXT NOT NULL,source TEXT NOT NULL,target TEXT NOT NULL,body TEXT NOT NULL,occurred_at BIGINT NOT NULL,data TEXT NOT NULL DEFAULT '{}');
 CREATE INDEX IF NOT EXISTS room_conversation_room ON room_conversation(room_id,id);
 CREATE TABLE IF NOT EXISTS room_conversation_state(room_id TEXT NOT NULL,channel TEXT NOT NULL,signature TEXT NOT NULL,revision BIGINT NOT NULL,PRIMARY KEY(room_id,channel));
 CREATE UNIQUE INDEX IF NOT EXISTS users_email_lower ON users(lower(email));
 CREATE INDEX IF NOT EXISTS swaps_booking ON swaps(booking_id,created_at);
 INSERT INTO schema_migrations(version,applied_at) VALUES(1,(extract(epoch FROM clock_timestamp())*1000)::bigint),(2,(extract(epoch FROM clock_timestamp())*1000)::bigint),(3,(extract(epoch FROM clock_timestamp())*1000)::bigint) ON CONFLICT DO NOTHING;
